    $reportProperty=seo_reporting_property($db);
    $anchor=null;if($reportProperty){$q=$db->prepare("SELECT MAX(data_date) FROM seo_observations WHERE grain='property' AND source='gsc_api' AND property_id=?");$q->execute([$reportProperty]);$anchor=$q->fetchColumn()?:null;}
    try{[$from,$to]=seo_period($period,$_GET['from']??null,$_GET['to']??null,$anchor);}catch(Throwable $e){$period='last7';[$from,$to]=seo_period($period,null,null,$anchor);}
    $stats=seo_cache($db,'stats_'.substr(hash('sha256',$reportProperty??''),0,12).'_'.$from.'_'.$to,300,static fn()=>seo_stats($db,$from,$to));
