    echo '<section class="card seo-card"><form method="get" class="seo-filter"><input type="hidden" name="section" value="overview"><div><label for="seo-period">Reporting period</label><select name="period" id="seo-period">';
    foreach(['latest'=>'Latest finalized day','last7'=>'Last 7 completed days','previous7'=>'Previous 7 days','last28'=>'Last 28 completed days','previous28'=>'Previous 28 days','custom'=>'Custom range'] as $v=>$label)echo '<option value="'.$v.'"'.($period===$v?' selected':'').'>'.$label.'</option>';
    echo '</select></div><div><label for="seo-from">From (custom)</label><input id="seo-from" type="date" name="from" value="'.seo_h($_GET['from']??'').'"></div><div><label for="seo-to">To (custom)</label><input id="seo-to" type="date" name="to" value="'.seo_h($_GET['to']??'').'"></div><button class="btn">Apply</button></form><p class="seo-muted">Showing '.seo_h($from).' to '.seo_h($to).' (Search Console Pacific Time). '.(int)($stats['observed_days']??0).' of '.((int)((strtotime($to)-strtotime($from))/86400)+1).' days have imported API property data. Totals cover only those observed days.</p></section>';
