}
if($section==='priority'||$section==='keywords'){
    $all=seo_keyword_rows($db,$section==='priority');$searchInput=$_GET['q']??'';$filter=mb_strtolower(trim(is_string($searchInput)?$searchInput:''));if($filter!=='')$all=array_values(array_filter($all,static fn($k)=>str_contains(mb_strtolower($k['keyword']),$filter)));
    $sort=seo_enum((string)($_GET['sort']??'priority'),['priority','keyword','country'],'priority');
