    echo '<section class="card seo-card"><h2>'.($section==='priority'?'Priority keywords':'All keywords').'</h2><p class="seo-muted">'.(int)$total.' matching keywords. Historical export positions are all-country/all-device period averages; dated positions require a completed API refresh.</p><form method="get" class="seo-filter"><input type="hidden" name="section" value="'.$section.'"><div><label for="seo-q">Find keyword</label><input id="seo-q" name="q" value="'.seo_h($_GET['q']??'').'"></div><div><label for="seo-sort">Sort</label><select id="seo-sort" name="sort"><option value="priority"'.($sort==='priority'?' selected':'').'>Priority</option><option value="keyword"'.($sort==='keyword'?' selected':'').'>Keyword A–Z</option><option value="country"'.($sort==='country'?' selected':'').'>Country A–Z</option></select></div><button class="btn">Search</button></form><div class="seo-table"><table><thead><tr><th>Keyword</th><th>Target</th><th>Scope</th><th>Priority</th><th>Latest date / position</th><th>Previous / movement</th><th>Impressions / clicks / CTR</th><th>Source</th><th>Employee</th><th>Action</th><th>Status</th></tr></thead><tbody>';
    foreach($rows as $k){$p=seo_keyword_performance($db,$k);$latest=$p['latest'];$prev=$p['previous'];$movement=$p['movement'];$hq=$db->prepare("SELECT position,period_start,period_end FROM seo_observations WHERE grain='query' AND source='gsc_export_2026-10-24' AND query_text=? LIMIT 1");$hq->execute([$k['keyword']]);$hist=$hq->fetch();
        $original=json_decode($k['source_snapshot_json']??'',true)?:[];
        $latestMetrics=$latest?$f((float)$latest['impressions'],0).' / '.$f((float)$latest['clicks'],0).' / '.((float)$latest['impressions']>0?$f((float)$latest['clicks']/(float)$latest['impressions']*100,2).'%':'No data'):'No data';
        echo '<tr><td><strong>'.seo_h($k['keyword']).'</strong><br><small>'.seo_h($k['category']).' · ID '.(int)$k['id'].'</small>'.(admin_can($user,'seo_manage')?' <a href="?section=keywords&edit='.(int)$k['id'].'">Edit</a>':'').'</td><td>'.seo_h($k['target_page']).'</td><td>'.seo_h($k['country']).' · '.seo_h($k['device']).'</td><td>'.seo_h($k['priority']).($k['is_primary']?' · Primary':'').'</td><td>'.($latest?seo_h($latest['data_date']).' · '.($latest['position']!==null?$f((float)$latest['position'],2):'No position'):'NO GSC DATA').($hist?'<br><small>Historical all-country: '.($hist['position']!==null?$f((float)$hist['position'],2):'No position').' ('.seo_h($hist['period_start']).'–'.seo_h($hist['period_end']).')</small>':'').'</td><td>'.($prev&&$prev['position']!==null?$f((float)$prev['position'],2):'NO COMPARABLE DATA').($movement!==null?'<br><strong class="'.($movement>=0?'seo-positive':'seo-negative').'">'.($movement>=0?'+':'').$f($movement,2).'</strong>':'').'</td><td>'.$latestMetrics.'</td><td>'.seo_h($latest?'GSC API':($hist?'GSC period export':'No GSC data')).'</td><td>'.seo_h($k['assigned_name']??'Unassigned').'</td><td>'.seo_h($k['recommended_action']??'').'</td><td>'.seo_h($original['Action status']??($k['active']?'Active':'Inactive')).'</td></tr>';
    }echo '</tbody></table></div>';
    if($page>1)echo '<a href="?section='.$section.'&q='.rawurlencode($filter).'&sort='.$sort.'&page='.($page-1).'">Previous</a> ';if($page*50<$total)echo '<a href="?section='.$section.'&q='.rawurlencode($filter).'&sort='.$sort.'&page='.($page+1).'">Next</a>';
    echo '</section>';
    if(admin_can($user,'seo_manage')){
        $editId=(int)($_GET['edit']??0);$edit=null;if($editId){$q=$db->prepare('SELECT * FROM seo_keywords WHERE id=?');$q->execute([$editId]);$edit=$q->fetch();}
