        foreach(['keyword'=>'Exact keyword','category'=>'Category','country'=>'Target country','target_page'=>'Canonical landing page'] as $field=>$label)echo '<div><label for="seo-'.seo_h($field).'">'.$label.'</label><input id="seo-'.seo_h($field).'" name="'.$field.'" value="'.seo_h($edit[$field]??($field==='country'?'All':'')).'"'.($field==='keyword'?' required':'').'></div>';
        echo '<div><label for="seo-priority">Priority</label><select id="seo-priority" name="priority">';foreach(['High','Medium','Low'] as $v)echo '<option'.(($edit['priority']??'Low')===$v?' selected':'').'>'.$v.'</option>';echo '</select></div><div><label for="seo-device">Device</label><select id="seo-device" name="device">';foreach(['All','Desktop','Mobile','Tablet'] as $v)echo '<option'.(($edit['device']??'All')===$v?' selected':'').'>'.$v.'</option>';echo '</select></div><div><label for="seo-assignee">Employee</label><select id="seo-assignee" name="assigned_user_id"><option value="">Unassigned</option>';foreach($users as $u)echo '<option value="'.(int)$u['id'].'"'.((int)($edit['assigned_user_id']??0)===(int)$u['id']?' selected':'').'>'.seo_h($u['name']).'</option>';echo '</select></div><div><label><input type="checkbox" name="is_primary" value="1" style="width:auto"'.(!empty($edit['is_primary'])?' checked':'').'> Primary tracked keyword</label><label><input type="checkbox" name="active" value="1" style="width:auto"'.(!$edit||!empty($edit['active'])?' checked':'').'> Active</label></div></div><button class="btn">Save keyword</button></form></section>';
