    $q=$db->prepare("SELECT property_id,data_date,source,clicks,impressions,ctr,position FROM seo_observations WHERE grain='property' AND data_date BETWEEN ? AND ? ORDER BY data_date DESC LIMIT 200");$q->execute([$from,$to]);$rows=$q->fetchAll();
