if($section==='google'){
    $connected=$db->query('SELECT property_id,connected_at,updated_at FROM seo_google_connections WHERE id=1')->fetch();
    echo '<section class="card seo-card"><h2>Search Console connection</h2><p>'.($connected?'Connected property: <strong>'.seo_h($connected['property_id']).'</strong> · Connected '.seo_h($connected['connected_at']):'Not connected. Administrator setup is required.').'</p><p class="seo-muted">Read-only scope only. Credentials and encryption key must remain outside public_html. No Google password or OTP is stored here.</p>';
    if(admin_can($user,'seo_connect')){echo '<div class="seo-actions"><form method="post" action="/admin/seo/action.php"><input type="hidden" name="csrf" value="'.$csrf.'"><input type="hidden" name="action" value="google_start"><button class="btn">'.($connected?'Reconnect':'Connect').' Google</button></form>';if($connected)echo '<form method="post" action="/admin/seo/action.php" onsubmit="return confirm(\'Disconnect Search Console? Saved ranking history stays.\')"><input type="hidden" name="csrf" value="'.$csrf.'"><input type="hidden" name="action" value="google_disconnect"><button class="btn alt">Disconnect</button></form>';echo '</div>';}
    echo '</section>';
    if(admin_can($user,'seo_connect')){$default=seo_setting($db,'default_period','last7');echo '<section class="card seo-card"><h2>Dashboard settings</h2><form method="post" action="/admin/seo/action.php"><input type="hidden" name="csrf" value="'.$csrf.'"><input type="hidden" name="action" value="settings_save"><label for="seo-default-period">Default reporting period</label><select id="seo-default-period" name="default_period">';foreach(['latest'=>'Latest available finalized day','last7'=>'Last 7 completed days','last28'=>'Last 28 completed days'] as $v=>$label)echo '<option value="'.$v.'"'.($default===$v?' selected':'').'>'.$label.'</option>';echo '</select><button class="btn">Save settings</button></form></section>';}
    if(admin_can($user,'seo_manage')){
        try{$preview=seo_import_preview($db);}catch(Throwable $e){$preview=[];echo '<div class="notice seo-error">'.seo_h($e->getMessage()).'</div>';}
        echo '<section class="card seo-card"><h2>Private historical import</h2><p>Source directory: <span class="seo-code">'.seo_h(seo_import_dir()).'</span>. Preview is read-only; import appends records and never changes source files.</p><div class="seo-table"><table><thead><tr><th>File</th><th>Rows</th><th>Status</th></tr></thead><tbody>';
        foreach($preview as $name=>$p)echo '<tr><td>'.seo_h($name).'</td><td>'.($p['rows']??'—').'</td><td>'.(empty($p['available'])?'Unavailable':($p['imported']?'Already imported':'Ready')).'</td></tr>';echo '</tbody></table></div><form method="post" action="/admin/seo/action.php" onsubmit="return confirm(\'Import available private reports into the SEO database?\')"><input type="hidden" name="csrf" value="'.$csrf.'"><input type="hidden" name="action" value="import"><button class="btn">Import available reports</button></form></section>';
    }
}
if($section==='exports'){
    echo '<section class="card seo-card"><h2>Protected CSV reports</h2><p>Exports require an active authorized admin session. Source, period and scope columns are included. Excel can open these CSV files.</p><ul>';
    foreach(['priority'=>'25 Priority Keywords','keywords'=>'All Keyword Performance','history'=>'Daily Ranking History','pages'=>'Landing Page Performance','weekly'=>'Weekly SEO Summary','tasks'=>'Employee Task Report'] as $type=>$label)echo '<li><a href="/admin/seo/export.php?type='.$type.'">'.seo_h($label).' CSV</a></li>';echo '</ul></section>';
}
admin_layout_end();
